{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "A high-transfer analogue with an aniline-piperazine-pyrimidine core achieved 77% absolute oral bioavailability in healthy volunteers in the fed state, directly showing that this scaffold class can be well absorbed despite high TPSA and a basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Linezolid, a polar drug with morpholine and acetamide groups, has almost 100% oral bioavailability in fasted healthy volunteers, demonstrating that high polar surface area and H-bond acceptors do not inherently cause F <20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Brigatinib, structurally very close to the query (aniline-piperazine, pyrimidine, aromatic substituents), had ~46% absolute oral bioavailability in healthy volunteers, providing a direct high-F anchor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Paliperidone ER, a polar heteroaromatic with a basic piperidine, has 28% absolute oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Rifapentine, a large macrocyclic antibiotic with many H-bond donors/acceptors, has 70% oral bioavailability in humans, showing that high molecular weight and polarity do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ketanserin, a fluorophenyl-piperidine-quinazolinedione, has ~60% absolute oral bioavailability in fasted subjects, supporting high F for a moderately polar basic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "A structurally related pyrimidine-piperazine-aniline analogue has ~20-25% oral bioavailability, at or above the threshold, providing a lower-bound supportive anchor.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues (transfer ~0.98) show absolute oral bioavailability between 20% and 100%, with several structurally similar aniline-piperazine-pyrimidine drugs at 46-77%. The physicochemical prior predicting low F is overridden by this consistent experimental evidence. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is included in the evidence set; extrapolation relies on high-transfer analogues.",
    "The query's food effect and formulation (e.g., fed/fasted, tablet) are not specified; food can affect the bioavailability of this compound class.",
    "Potential efflux transporter and first-pass metabolism contributions are not directly measured for the query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C24", "C21", "C14", "C25", "C09", "C03", "C19"],
      "decision_effect": "changed",
      "direction": "supportive",
      "family": "oral bioavailability analogues"
    }
  ],
  "revision_action": "initial"
}

